const express = require('express');
const execa = require('execa');
const { CareRelationship } = require('../models/careRelationship');

const app = express();
app.use(express.json());

app.post('/api/patients/export-summary', async (req, res) => {
  if (!req.session || !req.session.practitionerId) {
    return res.status(401).json({ error: 'Practitioner authentication required' });
  }

  const { patientId } = req.body;

  // Verify clinical care relationship between practitioner and patient
  const hasAccess = await CareRelationship.findOne({
    practitionerId: req.session.practitionerId,
    patientId: patientId,
    active: true
  });

  if (!hasAccess && req.session.role !== 'HOSPITAL_CHIEF_MEDICAL_OFFICER') {
    return res.status(403).json({ error: 'Forbidden: no active care relationship with this patient' });
  }

  try {
    const { stdout } = await execa('node', [
      './bin/export-patient-summary.js',
      '--patient-id',
      patientId,
      '--practitioner-id',
      req.session.practitionerId
    ]);

    const result = JSON.parse(stdout);
    res.json({
      patientId,
      summaryPdfPath: result.outputPath,
      recordCount: result.totalEntries
    });
  } catch (err) {
    res.status(500).json({ error: 'Failed to compile patient summary' });
  }
});

app.listen(8085);
